parameters.jsCode:
// ============================
// 路由器：字段提取 + 路由分类 + 消息去重（5 分钟窗口，防 Cloud API 重试）
// v2 变化：老板直发消息单独 boss_direct 路由（静默忽略，v1 会误回「只能处理文字」）；
//          新增 location / audio 路由；lead 采集支线已按老板决定整条移除。
// ============================

const entry = $input.first().json.body.entry[0].changes[0].value;
const msg = entry.messages[0];
const BOSS_PHONE = '60165014501';

const staticData = $getWorkflowStaticData('global');
const nowTs = Date.now();
const seen = staticData.seenMessages || {};
for (const k of Object.keys(seen)) {
  if (nowTs - seen[k] > 5 * 60 * 1000) delete seen[k];
}
if (msg.id && seen[msg.id]) {
  return [];
}
if (msg.id) {
  seen[msg.id] = nowTs;
  staticData.seenMessages = seen;
}

const phone = msg.from;
const type = msg.type;
const text = msg.text?.body ?? '';
const imageId = msg.image?.id ?? '';
const caption = msg.image?.caption ?? '';
const contextId = msg.context?.id ?? '';
const isBoss = phone === BOSS_PHONE;
const hasContext = !!msg.context;
const lat = msg.location?.latitude ?? null;
const lng = msg.location?.longitude ?? null;
const locName = msg.location?.name ?? '';
const locAddress = msg.location?.address ?? '';

let route = 'fallback';
if (isBoss && hasContext && type === 'text' && text) {
  route = 'boss_reply'; // 只有「引用+文字」才算转达指令；引用图片/贴纸会被静默忽略
} else if (isBoss) {
  route = 'boss_direct'; // 老板随手消息：静默忽略
} else if (type === 'image') {
  route = 'image';
} else if (type === 'location') {
  route = 'location';
} else if (type === 'audio') {
  route = 'audio';
} else if (type === 'text' && text) {
  route = 'customer_text';
}

return [{
  json: {
    phone, type, text, imageId, caption, contextId,
    isBoss, hasContext, route,
    msgId: msg.id || '',
    lat, lng, locName, locAddress
  }
}];

// ============================
// 防抖闸门：wa_buffer 里 msg_id='PROCESSED' 的行是水位线。
// 只有「等待期后仍是该客户最新一条真实消息」的执行继续往下走，
// 并把水位线以上的多条消息合并成一段交给 AI —— 客户连发三条只回一次。
// 两个关键点（review 修过的坑）：
// 1. 水位线 ts 用「本次吞掉的最大消息 ts」（maxTs 传给 Buffer Mark），
//    不能用打水位线那一刻的 $now —— 否则 Read 和 Mark 之间落进来的新消息会被永久吞掉。
// 2. SYS- 开头的系统注记行（定位报价等）只并入上下文，不参与「谁是最新」判定 ——
//    否则客户先发文字再发定位，文字那条会被 SYS 行顶掉、永远没人回。
// ============================

const me = $('Router').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && String(r.phone) === String(me.phone));

const marks = rows.filter(r => String(r.msg_id) === 'PROCESSED').map(r => Number(r.ts) || 0);
const lastMark = marks.length ? Math.max(...marks) : 0;
const pending = rows
  .filter(r => String(r.msg_id) !== 'PROCESSED' && (Number(r.ts) || 0) > lastMark)
  .sort((a, b) => (Number(a.ts) || 0) - (Number(b.ts) || 0));

// 我这条已在上一个水位线之下 = Cloud API 重试进来的旧消息 → 静默退出
const mine = rows.find(r => String(r.msg_id) === String(me.msgId));
if (mine && (Number(mine.ts) || 0) <= lastMark) return [];

// Sheet 抽风没读到我这条 → 绝不能吃掉客户消息，退化成单条处理
const realPending = pending.filter(r => !String(r.msg_id).startsWith('SYS-'));
if (realPending.length === 0) {
  return [{ json: { phone: me.phone, text: me.text, mergedCount: 1, maxTs: Date.now(), degraded: true } }];
}

// 「最新」只看真实客户消息（SYS- 注记不算数）；不是最新 → 更新的执行会连我一起处理
const latest = realPending[realPending.length - 1];
if (String(latest.msg_id) !== String(me.msgId)) return [];

const text = pending.map(r => String(r.text || '')).filter(Boolean).join('\n');
const maxTs = Math.max(...pending.map(r => Number(r.ts) || 0));
return [{ json: { phone: me.phone, text, mergedCount: pending.length, maxTs } }];

// ============================
// Context Builder v2：菜单/配送/促销/发图清单（同 v1）+ 客户档案注入（新）。
// 所有外部读取都 fail-safe —— 任何一路挂了给出安全兜底文案，绝不让 AI 编。
// ============================

const menuApi = $('Get Live Menu').first()?.json || {};
const apiOk = typeof menuApi.today_menu === 'string' && menuApi.today_menu.length > 0;
const deliveryContext = apiOk ? menuApi.delivery_context : '';
const deliveryLabel = apiOk ? menuApi.delivery_label : '';
const todayMenu = apiOk
  ? menuApi.today_menu
  : '【系统提示】菜单服务暂时读取不到。不要凭记忆报任何菜名或价格，直接在回复开头加 [求救老板]，请客户稍等。';

const promoRow = $('Get Promo').first()?.json || {};
const promoActive = promoRow.active === true || String(promoRow.active).toLowerCase() === 'true';
const promoText = (promoActive && promoRow.text) ? String(promoRow.text) : '暂无促销活动。';

const dishRows = $('Get Dishes').all().map(i => i.json).filter(d => {
  if (!d || !d.dish_id) return false;
  const a = d.active;
  return a === true || String(a ?? '').toLowerCase() === 'true';
});
const dishIdList = dishRows.length
  ? dishRows.map(d => {
      const aliases = String(d.aliases ?? '').trim();
      return `- ${d.dish_id}${aliases ? `（${aliases}）` : ''}：${d.name_zh} RM${d.price}`;
    }).join('\n')
  : '（暂无可发图菜单）';

const cust = $('Get Customer').first()?.json || {};
const customerContext = typeof cust.contextBlock === 'string' && cust.contextBlock
  ? cust.contextBlock
  : '【客户档案】查询暂时失败 —— 不要假设客户身份，正常接待即可。';

const gate = $('Debounce Gate').first().json;
return [{
  json: {
    phone: gate.phone,
    text: gate.text,
    delivery_context: deliveryContext,
    delivery_label: deliveryLabel,
    today_menu: todayMenu,
    promo_text: promoText,
    dish_id_list: dishIdList,
    customer_context: customerContext
  }
}];

// ============================
// 后处理 v2：统一求救标记 —— 只有 [求救老板]，并用 /\[求救[^\]]*\]/ 兜底，
// 任何带「求救」的方括号标记都会被识别 + 剥除（修复 v1 双标记漏网 bug）。
// ============================

const aiReply = $input.first().json.output || '';
const phone = $('Router').first().json.phone;
const customerMsg = $('Debounce Gate').first().json.text || $('Router').first().json.text || '';

const needEscalate = /\[求救[^\]]*\]/.test(aiReply);
const needQR = /\[SEND_QR\]/i.test(aiReply);
const dishMatch = aiReply.match(/\[SEND_DISH:([a-z0-9_\-]+)\]/i);

let cleanReply = aiReply
  .replace(/\[求救[^\]]*\]/g, '')
  .replace(/\[SEND_QR\]/gi, '')
  .replace(/\[SEND_DISH:[a-z0-9_\-]+\]/gi, '')
  .trim();

let action = 'normal';
if (needEscalate) action = 'escalate';
else if (needQR) action = 'send_qr';
else if (dishMatch) action = 'send_dish';

if (!cleanReply) {
  action = 'escalate';
  cleanReply = '不好意思亲！这个碗妈得跟老板确认一下，稍等哦 ❤️';
}

return [{
  json: {
    phone,
    customerMsg,
    reply: cleanReply,
    action,
    dishId: dishMatch ? dishMatch[1].toLowerCase() : ''
  }
}];

