// ============================
// 位置 pin 报价：坐标直接算档位/运费（与网站同一套 deliveryUtils 口径），
// 并往 wa_buffer 写一条系统注记 —— 客户下一条文字消息会连同定位信息一起进 AI。
// ============================

const r = $('Zone by Pin').first()?.json || {};
const me = $('Router').first().json;
const place = me.locName || me.locAddress || '';

let reply, note, needEscalate;
if (typeof r.fee === 'number') {
  const th = r.threshold;
  reply = `收到定位啦 📍 ${place ? place + ' ' : ''}距离碗妈厨房约 ${r.distanceKm}km，运费 RM ${r.fee}${th ? `，菜品满 RM ${th} 就免运费哦` : '（这个距离是固定运费）'}。想下单直接告诉碗妈要哪道菜 ❤️`;
  note = `[系统注记：客户发来定位 ${place} ≈${r.distanceKm}km，运费 RM ${r.fee}${th ? `｜满 RM ${th} 免运` : '｜固定运费'}。下单可以直接用这个定位当地址。]`;
  needEscalate = false;
} else if (r.tier === 'outside') {
  reply = `亲爱的，你的位置离碗妈厨房约 ${r.distanceKm}km，超出目前 25km 的配送范围了 😢 碗妈让老板看看有没有别的安排，稍等哦`;
  note = `[系统注记：客户定位超出配送范围（≈${r.distanceKm}km）]`;
  needEscalate = true;
} else {
  reply = '定位收到啦！碗妈让老板帮你确认一下配送范围，稍等哦 ❤️';
  note = '[系统注记：客户发来定位但运费查询失败，需要人工确认]';
  needEscalate = true;
}

return [{ json: { phone: me.phone, reply, note, needEscalate, msgId: me.msgId } }];

